        steps.push_back(p - prev);
        prev = p;
    }

    // 约瑟夫环递推，f 表示 0 下标答案
    int f = 0;
    for (int m = 2; m <= n; m++) {
        f = (f + steps[n - m]) % m;
    }

    return f + 1;
